head.script:
/**
 * 전역 변수
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_searchCdInf_target = 'data:json,{"id":"dlt_comTaskTypCd","key":"data.dlt_comTaskTypCd"}';

scwin.srchDvs = '';

/**
 * 화면 pageload 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.onpageload = function() {
    // parameter
    var param   = com.data.getParameter() || ssgo.getParameter();
    
    var loginTyp = ssgo.getSessionStorage("LOGIN_INFO", "loginTyp");
    if(loginTyp == "S") {
        var ssoMsg = "현재 전자소송포털 통합인증(SSO)을 통한 나의사건검색을 이용중입니다.";
        txt_useSsoMsg.show("");
        txt_useSsoMsg.setValue(ssoMsg);
        scwin.srchDvs = '09';   //SSO 나의사건목록조회
    } else {
        txt_useSsoMsg.hide();
        scwin.srchDvs = '07';   //공인인증 나의사건목록조회
    }
    
    // 공인인증서 로그인 화면에서 이동 됬을 경우 세션스토리지의 코드, 목록, 검색조건을 삭제한다.
    if(param.initYn === "Y") {
        // 1. 세션스토리지 삭제(코드, 나의사건목록, 검색조건)
        var storage = ssgo.STORAGE.MCL_COND;
        ssgo.removeSessionStorageSection(storage.ID);

        // 2. 화면 로드시 기본정보(코드등) 조회 submission
        scwin.sbm_selectCodeInfo();        
    
    // 나의목록에서 상세로 이동 후 Back할경우 기존의 세션스토리지의 코드, 목록, 검색조건을 셋팅한다.
    } else {
        scwin.ufn_setSessionStorageCondition();
    }

};

/**
 * 화면 pageunload 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.onpageunload = function() {
};


/**
 *********************************************************************************************************
 * Submission Event Handler
 *********************************************************************************************************
 */
/**
 * 법원,공통업무유형 관련 코드조회
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_selectCodeInfo = function() {
    var cortCd = "";
    dma_searchCdInf.set("cortCd", cortCd);
    dma_searchCdInf.set("cdScope", "ALL");   // 법원,공통업무유형 둘다 조회함

    com.executeSubmission(sbm_searchCdInf);
};

/**
 * 코드 조회 submission done 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_searchCdInf_submitdone = function(e) {
    // 전체법원 코드 셋팅
    if(e.responseJSON.data.cortAllYn == "Y") {
        sbx_cortCd.addItem("", "------------", null, false);
        sbx_cortCd.addItem("000000", "전체", null, false);
        ssgo.setSessionStorage("LOGIN_INFO", "cortAllYn", e.responseJSON.data.cortAllYn); // 전체법원
    }
    
    var loginTyp = e.responseJSON.data.loginTyp;
    if(!scutilo.isEmpty(loginTyp)) {

        if(loginTyp == "S") {
            var ssoMsg = "현재 전자소송포털 통합인증(SSO)을 통한 나의사건검색을 이용중입니다.";
            txt_useSsoMsg.show("");
            txt_useSsoMsg.setValue(ssoMsg);
            scwin.srchDvs = '09';   //SSO 나의사건목록조회

            // 세션스토리지 로그인타입 저장
            ssgo.setSessionStorage("LOGIN_INFO", "loginTyp", e.responseJSON.data.loginTyp); // 로그인타입
        } else {
            txt_useSsoMsg.hide();
            scwin.srchDvs = '07';   //공인인증 나의사건목록조회
        }        
    }


};    


/**
 * 나의사건 목록 조회 submission done 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_search_submitdone = function(e) {
    
    // 1. 나의사건 목록의 법원명, 공통업무유형명 셋팅
    if(!scutilo.isEmpty(dlt_myCsList)) {
        // 법원,공통업무유형코드의 코드명을 가져온다.
        for(let i = 0; i < dlt_myCsList.getRowCount(); i++) {
            var rowData = dlt_myCsList.getRowJSON(i);
            // 법원명 셋팅
            var arrCortCd = dlt_cortCd.getMatchedArray("code", rowData.cortCd).data;
            if(arrCortCd.length > 0) {
                dlt_myCsList.setCellData(i,"cortNm", arrCortCd[1]);
            }
            //  셋팅
            var arrComTaskTypCd = dlt_comTaskTypCd.getMatchedArray("comTaskTypCd", rowData.comTaskTypCd).data;
            if(arrComTaskTypCd.length > 0) {
                dlt_myCsList.setCellData(i,"comTaskTypNm", arrComTaskTypCd[1]);
            }
        }
    }

    // 2. session storage에 나의사건목록, 검색조건코드(법원코드,공통업무유형코드), 선택된 검색조건(법원코드,공통업무유형코드)을 저장한다.
    // 2-1. 기존 스토리지 삭제
    var storage = ssgo.STORAGE.MCL_COND;
    ssgo.removeSessionStorageSection(storage.ID);    
    
    // 2-2. 코드 셋팅
    ssgo.setSessionStorage(storage.ID, storage.KIND.cortCdList, JSON.stringify(dlt_cortCd.getAllJSON()));               //법원
    ssgo.setSessionStorage(storage.ID, storage.KIND.comTaskTypCdList, JSON.stringify(dlt_comTaskTypCd.getAllJSON()));   //공통업무유형

    // 2-3. 선택된 코드 셋팅
    ssgo.setSessionStorage(storage.ID, storage.KIND.cortCd, sbx_cortCd.getValue());                                 // 선택된 법원
    ssgo.setSessionStorage(storage.ID, storage.KIND.comTaskTypCd, JSON.stringify(ccb_taskCd.getSelectedInfo()));    // 선택된 공통업무유형

    // 2-4. 나의사건목록 셋팅
    ssgo.setSessionStorage(storage.ID, storage.KIND.myCsList, ssgo.encode(JSON.stringify(dlt_myCsList.getAllJSON())));
    
};    

/**
 * 코드 조회 submission error 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_searchCdInf_submiterror = function(e) {
    ssgo.printSubmiterror(e);
};

/**
 * 사건조회 조회 submission error 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_search_submiterror = function(e) {
    //if(typeof e.errorType != "undefined") {	// 에러시
        com.win.moveUrl(ssgo.getCtxtPathUrl(ssgo.getProperties("clt.ssgo.mycs.login")), {});
    //}    
};

/**
 *********************************************************************************************************
 * Event Handler
 *********************************************************************************************************
 */
/**
 * 법원코드 onchange 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.sbx_cortCd_onchange = function(info) {
    dma_searchCdInf.set("cortCd", sbx_cortCd.getValue());
    dma_searchCdInf.set("cdScope", "");

    sbm_searchCdInf.target = scwin.sbm_searchCdInf_target;
    com.executeSubmission(sbm_searchCdInf);
};

/**
 * 검색 클릭 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */	
scwin.btn_srchCs_onclick = function(e) {
    
    // 법원 정합성 체크
    if( sbx_cortCd.getValue().indexOf("A") === 0 ) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0002, "법원을"), function() {  //I_0002: "법원을 선택하십시오."
            sbx_cortCd.focus();
        });
        return false; 
    }

    // 사건종류 정합성 체크
    if(ccb_taskCd.getSelectedInfo().length === 0) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0002, "사건종류를") , function () { //I_0002: "사건종류를 선택하십시오."
            ccb_taskCd.focus();
        });
        
        return false;
    }

    //법원을 '전체' 선택할 경우 사건종류는 1건만 선택가능
    if(sbx_cortCd.getValue() === "000000" && ccb_taskCd.getSelectedInfo().length > 1) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0016) , function () { //I_0016: "법원을 '전체'로 선택 시 사건종류는 1개만 선택 가능합니다."
            ccb_taskCd.focus();
        });
        
        return false;        
    }

    // 사건종류 3개까지만 선택 가능하게 처리
    if(ccb_taskCd.getSelectedInfo().length > 3) {
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(ssgomsg.SSGO.I_0010) , function () { //I_0010: "사건종류는 3개까지만 선택 가능합니다."
            ccb_taskCd.focus();
        });
        
        return false;
    }
    
    dma_search.set("cortCd", sbx_cortCd.getValue());
    dma_search.set("comTaskTypCd", null);
    dma_search.set("comTaskTypCd", ccb_taskCd.getSelectedInfo());
    dma_search.set("srchDvs", scwin.srchDvs);   //검색구분
    
    dlt_search_comTaskTypCd.removeAll();
    dlt_search_comTaskTypCd.setJSON(ccb_taskCd.getSelectedInfo());

    com.executeSubmission(sbm_search);
};


/**
 * 나의사건목록 사건번호 선택
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.myCsSrchRsltGrid_oncellclick = function(row,col,colId) {
    var dltObj = com.util.getGridViewDataList(this);
    
    // 사건번호 Cell 클릭시 
    if (col == 1) {
        var param = dltObj.getRowJSON(row);
        param.captchaAnswer = '';   // 캡챠정보 삭제
        if(scwin.srchDvs == "07") {
            param.srchDvs = "08"; //검색구분 : 공인인증검색후사건번호검색
        } else if(scwin.srchDvs == "09"){
            param.srchDvs = "10"; //검색구분 : SSO검색후사건번호검색
        }
        param.myCslistLinkYn    = 'Y';  // 나의사건 리스트 접근여부
        
        param.csYear   = param.csNo.substring(0,4);
        param.csDvsCd  = param.csNo.substring(4,7);
        param.csSerial = param.csNo.substring(7);
        
        com.win.moveUrl(ssgo.getCtxtPathUrl(ssgo.getProperties("clt.ssgo.rslt.csinfo")), param);        
    }
};


/**
 *********************************************************************************************************
 * Validate 
 *********************************************************************************************************
 */



/**
 *********************************************************************************************************
 * User Function
 *********************************************************************************************************
 */

/**
 * 세션스토리지 정보를 셋팅한다.
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */	
scwin.ufn_setSessionStorageCondition = function() {
    // 1. 나의사건검색 스토리지 선언
    var storage = ssgo.STORAGE.MCL_COND;

    // 2. 나의사건 목록 셋팅
    var myCsList = ssgo.getSessionStorage(storage.ID, storage.KIND.myCsList);
    dlt_myCsList.removeAll();
    dlt_myCsList.setJSON(JSON.parse(ssgo.decode(myCsList)));

    // 3. 법원코드 셋팅
    var cortCdList = ssgo.getSessionStorage(storage.ID, storage.KIND.cortCdList);
    var cortCd     = ssgo.getSessionStorage(storage.ID, storage.KIND.cortCd);
    dlt_cortCd.removeAll();
    dlt_cortCd.setJSON(JSON.parse(cortCdList));

    // 전체법원 셋팅
    var cortAllYn = ssgo.getSessionStorage("LOGIN_INFO", "cortAllYn");
    if(cortAllYn == "Y") {
        sbx_cortCd.addItem("", "------------", null, false);
        sbx_cortCd.addItem("000000", "전체", null, false);
    }
    
    sbx_cortCd.setEventPause(null, true);  // event lock
    sbx_cortCd.setValue(cortCd);
    sbx_cortCd.setEventPause(null, false);  // event unlock
    
    // 4. 공통업무유형코드 셋팅
    var comTaskTypCdList = ssgo.getSessionStorage(storage.ID, storage.KIND.comTaskTypCdList);
    var comTaskTypCd     = ssgo.getSessionStorage(storage.ID, storage.KIND.comTaskTypCd);    
    dlt_comTaskTypCd.removeAll();
    dlt_comTaskTypCd.setJSON(JSON.parse(comTaskTypCdList));
    ccb_taskCd.setSelectedInfo(JSON.parse(comTaskTypCd))
};

/**
 * 사건종류 포커스 처리
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2025.02.11.   최주한       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ccb_taskCd_onfocus = function(e) {

    //브라우저 및 PC에 따라 포커스 도망가는 이슈가 있어서 추가함
    ccb_taskCd.focus();
    
};
